import json
from pathlib import Path


_POLICY_PATH = Path(__file__).parent / "policy.json"


def load_policy() -> dict:
    return json.loads(_POLICY_PATH.read_text(encoding="utf-8"))


def can(user: dict, action: str, object: str, record: dict) -> bool:
    policy = load_policy()

    role = user.get("ROLE_ID", "")
    matching_grant = None

    for grant in policy.get("grants", []):
        if (
            grant.get("role") == role
            and grant.get("object") == object
            and grant.get("action") == action
        ):
            matching_grant = grant
            break

    if matching_grant is None:
        return False

    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    if role == policy.get("admin_role"):
        return True

    scope = matching_grant.get("scope")

    if scope == "ALL":
        return True
    if scope == "TEAM":
        return bool(user.get("TEAM_CD", "") == record.get("TEAM_CD", ""))
    if scope == "OWN":
        return bool(record.get("OWNER_UID", "") == user.get("USR_ID", ""))
    if scope == "NONE":
        return False

    return False
